extractor:
function extract(raw, memory, info) {
  var FRAME_MS = 16.67;
  var DEFAULT_STEP = 3;
  var POP_TOL = 5;
  var SEAM_BAR = 179.5;
  var SEAM_DOT = 179.7;
  var STILL_OVER = 20;
  var STALE_MAX = 30;
  var STEP_KEEP = 9;
  function wrap180(x) { return ((x + 180) % 360 + 360) % 360 - 180; }
  function mod360(x) { return (x % 360 + 360) % 360; }
  function r1(x) { return Math.round(x * 10) / 10; }
  function near(p, q) { return !!(p && q) && Math.abs(p.x - q.x) + Math.abs(p.y - q.y) <= 3; }
  function median(a) { var b = a.slice().sort(function (x, y) { return x - y; }); return b[Math.floor((b.length - 1) / 2)]; }
  function isRed(t) {
    if (t === undefined || t === null) return false;
    var n = typeof t === 'number' ? t : parseInt(String(t).replace('#', '').replace('0x', ''), 16);
    if (isNaN(n)) return false;
    var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    return r >= 176 && g < 112 && b < 112;
  }
  // a decision taken on this frame lands lagMs later, after kLo or kHi more animation frames
  var lag = info ? Number(info.lagMs) : 0;
  if (!isFinite(lag) || lag < 0) lag = 0;
  var lagF = lag / FRAME_MS;
  var kLo = Math.floor(lagF), kHi = lag > 0 ? kLo + 1 : 0;
  var objs = (raw && raw.objects) || [];
  var ring = null, bar = null, dots = [], texts = [], rest = [];
  var i, k, o, nm;
  for (i = 0; i < objs.length; i++) {
    o = objs[i];
    if (!o) continue;
    if (o.text !== undefined && o.text !== null) { texts.push(o); continue; }
    nm = ((o.tex || '') + ' ' + (o.frame || '') + ' ' + (o.name || '')).toLowerCase();
    if (!ring && nm.indexOf('ring') >= 0) ring = o;
    else if (!bar && (nm.indexOf('bar') >= 0 || nm.indexOf('needle') >= 0 || nm.indexOf('pointer') >= 0)) bar = o;
    else if (nm.indexOf('ball') >= 0 || nm.indexOf('dot') >= 0 || nm.indexOf('target') >= 0) dots.push(o);
    else rest.push(o);
  }
  var others = [], needDot = dots.length === 0;
  for (i = 0; i < rest.length; i++) {
    o = rest[i];
    var w = o.w || 0, h = o.h || 0;
    if (!ring && w >= 200 && Math.abs(w - h) < 0.2 * w) ring = o;
    else if (!bar && h > 0 && w >= 4 * h) bar = o;
    else if (needDot && w > 0 && w <= 120 && Math.abs(w - h) < 0.3 * w) dots.push(o);
    else others.push(o);
  }
  var cx = ring ? ring.x : (bar ? bar.x : 0), cy = ring ? ring.y : (bar ? bar.y : 0);
  // raw bar angle: +180 is kept apart from -180, because the game compares raw angles
  var barA = bar ? Number(bar.a || 0) : 0;
  if (!isFinite(barA)) barA = 0;
  if (barA > 180 || barA < -180) barA = wrap180(barA);
  if (!memory.init) {
    memory.init = true; memory.t = 0; memory.pops = 0; memory.still = 0; memory.over = false;
    memory.prevA = null; memory.prevDot = null; memory.dir = 1; memory.dirKnown = false; memory.steps = [];
    memory.lastRevT = -99; memory.lastJumpT = -99; memory.stale = null; memory.staleT = -99; memory.pend = null;
  }
  if (!memory.steps) memory.steps = [];
  memory.t++;
  var t = memory.t;
  var delta = (memory.prevA === null || !bar) ? 0 : wrap180(barA - memory.prevA);
  var moved = Math.abs(delta) > 0.3;
  memory.still = (moved || memory.prevA === null) ? 0 : memory.still + 1;
  var over = !bar || isRed(bar.tint) || memory.still >= STILL_OVER;
  if (memory.over && !over) {
    memory.pops = 0; memory.dir = 1; memory.dirKnown = false; memory.steps = []; memory.prevDot = null;
    memory.lastRevT = -99; memory.lastJumpT = -99; memory.stale = null; memory.pend = null;
  }
  var cands = [];
  for (i = 0; i < dots.length; i++) if (!near(dots[i], memory.stale)) cands.push(dots[i]);
  if (!cands.length) cands = dots;
  var dot = null, best = 1e9;
  for (i = 0; i < cands.length; i++) {
    var da = Math.atan2(cands[i].y - cy, cands[i].x - cx) * 180 / Math.PI;
    var gg = mod360((da - barA) * memory.dir);
    if (gg > 330) gg -= 360;
    if (gg < best) { best = gg; dot = cands[i]; }
  }
  var jumped = !!(dot && memory.prevDot && !near(dot, memory.prevDot));
  var clear = Math.abs(delta) >= 1.5 && Math.abs(delta) < 60;
  var sgn = delta > 0 ? 1 : -1;
  var reversed = false;
  if (!over && clear) {
    if (!memory.dirKnown) { memory.dir = sgn; memory.dirKnown = true; }
    else if (sgn !== memory.dir) {
      reversed = true;
      memory.dir = sgn;
      if (t - memory.lastRevT > 3) {
        memory.pops++;
        memory.lastRevT = t;
        if (dot && !jumped && t - memory.lastJumpT > 3) { memory.stale = { x: dot.x, y: dot.y }; memory.staleT = t; }
      }
    } else {
      memory.steps.push(Math.abs(delta));
      if (memory.steps.length > STEP_KEEP) memory.steps.shift();
    }
  }
  if (!over && jumped) {
    memory.lastJumpT = t;
    if (t - memory.lastRevT > 3) {
      memory.pops++;
      memory.lastRevT = t;
      if (!clear && memory.dirKnown) memory.dir = -memory.dir;
    }
  }
  if (memory.stale && ((dot && !near(dot, memory.stale)) || t - memory.staleT > STALE_MAX)) memory.stale = null;
  var stale = !!(memory.stale && dot && near(dot, memory.stale));
  // a tap decided at the last tap moment may still be on its way until a pop shows or the bar has run past its landing
  var pending = false;
  if (memory.pend) {
    if (over || reversed || jumped) memory.pend = null;
    else {
      memory.pend.moved += Math.abs(delta);
      if (memory.pend.moved < memory.pend.limit) pending = true;
      else memory.pend = null;
    }
  }
  var dir = memory.dir;
  // decisions span whole frames, so the smallest cluster of recent moves is the per-frame step
  var step = DEFAULT_STEP;
  if (memory.steps.length) {
    var mn = Math.min.apply(null, memory.steps), small = [];
    for (i = 0; i < memory.steps.length; i++) if (memory.steps[i] < 1.5 * mn) small.push(memory.steps[i]);
    step = median(small);
  }
  step = Math.max(1, Math.min(20, step));
  var dotA = 0, dotDist = 0, gNow = 0, edgeTol = 8;
  if (dot) {
    dotA = Math.atan2(dot.y - cy, dot.x - cx) * 180 / Math.PI;
    if (dotA >= 180) dotA -= 360;
    dotDist = Math.sqrt((dot.x - cx) * (dot.x - cx) + (dot.y - cy) * (dot.y - cy));
    gNow = mod360((dotA - barA) * dir);
    if (gNow > 330) gNow -= 360;
    if (dotDist > 1) edgeTol = Math.atan2((dot.w || 50) / 2, dotDist) * 180 / Math.PI;
    edgeTol = Math.max(POP_TOL + 1, Math.min(12, edgeTol));
  }
  var lead = lagF * step;
  var gap = gNow - lead;
  // bar n frames ahead: gap to the dot centre, on the 180 line, on the dot's side of it
  function gapAt(n) { return gNow - n * step; }
  function barAt(n) { return n === 0 ? barA : wrap180(barA + dir * n * step); }
  function onSeamAt(n) { return Math.abs(barAt(n)) >= SEAM_BAR; }
  function sideAt(n) { return Math.abs(barAt(n) - dotA) <= 180; }
  function popAt(n) { return !!dot && Math.abs(gapAt(n)) <= POP_TOL && !onSeamAt(n) && sideAt(n); }
  function popAll(a, b) { for (var n = a; n <= b; n++) if (!popAt(n)) return false; return true; }
  var pNow = popAll(kLo, kHi), mayNow = false, barOnSeam = false, seamSplit = false;
  for (k = kLo; bar && k <= kHi; k++) {
    if (onSeamAt(k)) barOnSeam = true;
    else if (dot && !sideAt(k)) seamSplit = true;
    if (dot && Math.abs(gapAt(k)) <= edgeTol && (onSeamAt(k) || sideAt(k))) mayNow = true;
  }
  var dotOnSeam = !!dot && Math.abs(dotA) >= SEAM_DOT;
  var ready = !over && !!dot && memory.dirKnown && clear && !reversed && !jumped && !stale && !pending;
  var tapOutcome = over ? 'none' : (!dot ? 'miss' : (!ready ? 'uncertain' : ((pNow && !dotOnSeam) ? 'pop' : (mayNow ? 'edge' : 'miss'))));
  var waitOutcome;
  if (over) waitOutcome = 'none';
  else if (!dot || stale || !memory.dirKnown || gapAt(kHi + 1) > POP_TOL) waitOutcome = 'safe';
  else if (popAll(kLo + 1, kHi + 1)) waitOutcome = (Math.abs(gap - step) < Math.abs(gap) && (!pNow || popAt(kHi + 2))) ? 'closer' : 'farther';
  else if (!pNow && popAll(kLo + 2, kHi + 2)) waitOutcome = 'closer';
  else waitOutcome = 'gameOver';
  if ((tapOutcome === 'pop' && (waitOutcome === 'farther' || waitOutcome === 'gameOver')) || (tapOutcome === 'edge' && waitOutcome === 'gameOver')) {
    memory.pend = { moved: 0, limit: (lagF + 0.5) * step };
  }
  var score = null, hud = [];
  for (i = 0; i < texts.length; i++) {
    var s = String(texts[i].text).trim();
    if (hud.length < 3) hud.push(s.slice(0, 24));
    if (score === null && /^[0-9]+$/.test(s)) score = parseInt(s, 10);
  }
  var unknown = [];
  for (i = 0; i < others.length && unknown.length < 4; i++) {
    o = others[i];
    unknown.push({ tex: String(o.tex || o.type || '?'), x: Math.round(o.x || 0), y: Math.round(o.y || 0), w: o.w || 0, h: o.h || 0,
      distFromCentre: Math.round(Math.sqrt((o.x - cx) * (o.x - cx) + (o.y - cy) * (o.y - cy))),
      angleDeg: Math.round(Math.atan2(o.y - cy, o.x - cx) * 180 / Math.PI) });
  }
  if (bar) memory.prevA = barA;
  memory.prevDot = dot ? { x: dot.x, y: dot.y } : null;
  memory.over = over;
  var state = {
    gameOver: over,
    pops: memory.pops,
    barMoving: moved,
    barReversed: reversed,
    dir: memory.dirKnown ? (dir > 0 ? 'clockwise' : 'counterclockwise') : 'unknown',
    barAngleDeg: r1(lag > 0 ? wrap180(barA + dir * lead) : barA),
    dotAngleDeg: dot ? r1(dotA) : null,
    dotVisible: !!dot,
    dotMoving: jumped,
    dotPopped: stale,
    popPending: pending,
    stepDeg: r1(step),
    leadDeg: r1(lead),
    gapDeg: r1(gap),
    gapNextDeg: r1(gap - step),
    popTolDeg: POP_TOL,
    edgeTolDeg: r1(edgeTol),
    seamSplit: seamSplit,
    barOnSeam: barOnSeam,
    dotOnSeam: dotOnSeam,
    ticksToDot: r1(gap / step),
    tapOutcome: tapOutcome,
    waitOutcome: waitOutcome
  };
  if (dots.length > 1) state.dotCount = dots.length;
  if (score !== null) state.score = score;
  if (hud.length) state.hudText = hud;
  if (unknown.length) state.unknown = unknown;
  return state;
}

teacher:
function teach(state) {
  if (!state || state.gameOver) return 'wait';
  var w = state.waitOutcome;
  if (state.tapOutcome === 'pop' && (w === 'farther' || w === 'gameOver')) return 'tap';
  if (state.tapOutcome === 'edge' && w === 'gameOver') return 'tap';
  return 'wait';
}
